mapper.select:
SELECT
	'예약' AS DOC_TYPE,
	RSV_NO AS DOC_NO,
	TRIP_ST_DTM AS TRIP_ST_DTM,
	TRIP_ED_DTM AS TRIP_ED_DTM,
	TRIP_PLACE AS TRIP_PLACE,
	FN_CM05M01_CD_TO_NM(TRIP_TYPE_CDS) AS TRIP_TYPE_NM
FROM TB_PM60M01
WHERE USER_ID = #{userId}

	AND RSV_NO != #{rsvNo}

AND SUBSTR(TRIP_ST_DTM, 1, 8) <= #{tripEdDate}
AND SUBSTR(TRIP_ED_DTM, 1, 8) >= #{tripStDate}

SELECT V.RSV_NO AS RSV_NO, V.CO_CD AS CO_CD, V.CLNT_CD AS CLNT_CD, V.VNDR_NM AS VNDR_NM, V.WORKER_NM AS WORKER_NM, NVL(V.WORK_ST_DT, V.WORK_DT) AS WORK_ST_DT, NVL(V.WORK_ED_DT, NVL(V.WORK_ST_DT, V.WORK_DT)) AS WORK_ED_DT, NVL(V.WORK_ST_DT, V.WORK_DT) AS WORK_DT, V.WORK_HOUR AS WORK_HOUR, V.TRIP_PLACE AS TRIP_PLACE, V.CLNT_PJT_CD AS CLNT_PJT_CD, V.CLNT_PJT_NM AS CLNT_PJT_NM, V.TRIP_TYPE_CDS AS TRIP_TYPE_CDS, FN_CM05M01_CD_TO_NM(V.TRIP_TYPE_CDS) AS TRIP_TYPE_CDS_NM, V.TRIP_DIV AS TRIP_DIV, FN_CM05M01_CD_TO_NM(V.TRIP_DIV) AS TRIP_DIV_NM, V.TRIP_COND_CD AS TRIP_COND_CD, FN_CM05M01_CD_TO_NM(V.TRIP_COND_CD) AS TRIP_COND_CD_NM, V.RSV_STS_CD AS RSV_STS_CD, FN_CM05M01_CD_TO_NM(V.RSV_STS_CD) AS RSV_STS_CD_NM, V.NIGHT_CNT AS NIGHT_CNT, V.DAY_CNT AS DAY_CNT, V.ETC AS ETC, V.CREAT_ID AS CREAT_ID, V.CREAT_DTTM AS CREAT_DTTM, V.UDT_ID AS UDT_ID, V.UDT_DTTM AS UDT_DTTM FROM TB_PM60M02 V WHERE V.CO_CD = 'GUN'
AND NVL(V.WORK_ST_DT, V.WORK_DT) <= #{monthEdDt} AND NVL(V.WORK_ED_DT, NVL(V.WORK_ST_DT, V.WORK_DT)) >= #{monthStDt}
ORDER BY V.VNDR_NM ASC, V.WORKER_NM ASC, NVL(V.WORK_ST_DT, V.WORK_DT) ASC
